def scaffold(
w: Optional[Union[int, str]] = None,
h: Optional[Union[int, str]] = None,
**kwargs: Any,
) -> Mark:
"""Scaffold mark - invisible guide for positioning."""
scaffold_kwargs: Dict[str, Any] = {}
if w is not None:
scaffold_kwargs["w"] = w
if h is not None:
scaffold_kwargs["h"] = h
scaffold_kwargs.update(kwargs)
return Mark("scaffold", **scaffold_kwargs)
